    private static final long M1 = 1000000007L, M2 = 1000000009L;
    private static final long B1 = 911382323L, B2 = 97266353L;

    private long sub(long[] h, long[] p, int l, int r, long mod) {
        long x = (h[r] - h[l] * p[r - l] % mod) % mod;
        return x < 0 ? x + mod : x;
    }

    public long sumScores(String s) {
        int n = s.length();
        long[] p1 = new long[n + 1], p2 = new long[n + 1];
        long[] h1 = new long[n + 1], h2 = new long[n + 1];
