            int x = s.charAt(i) - 'a' + 1;
            p1[i + 1] = p1[i] * B1 % M1;
            p2[i + 1] = p2[i] * B2 % M2;
            h1[i + 1] = (h1[i] * B1 + x) % M1;
            h2[i + 1] = (h2[i] * B2 + x) % M2;
        }
        long ans = 0;
        for (int i = 0; i < n; i++) {
            int lo = 0, hi = n - i;
            while (lo < hi) {
                int mid = (lo + hi + 1) / 2;
                boolean ok = sub(h1, p1, 0, mid, M1) == sub(h1, p1, i, i + mid, M1)
                        && sub(h2, p2, 0, mid, M2) == sub(h2, p2, i, i + mid, M2);
