class Solution {
    vector<int> prefixFunction(const string& p) {
        int m = (int)p.size();
        vector<int> pi(m);
        int j = 0;
        for (int i = 1; i < m; ++i) {
            while (j && p[i] != p[j]) j = pi[j - 1];
            if (p[i] == p[j]) ++j;
            pi[i] = j;
        }
        return pi;
    }
    string uppers(const string& s) {
        string t;
        for (char c : s) if (c >= 'A' && c <= 'Z') t += c;
        return t;
    }
    bool kmpEqual(const string& a, const string& b) {
        if (a.size() != b.size()) return false;
        if (a.empty()) return true;
        string t = a + "#" + b;
        return prefixFunction(t).back() == (int)a.size();
    }
public:
    vector<bool> camelMatch(vector<string>& queries, string pattern) {
        vector<int> pi = prefixFunction(pattern);
        (void)pi;
        string pu = uppers(pattern);
        int m = (int)pattern.size();
        vector<bool> ans;
        for (auto& q : queries) {
            if (!kmpEqual(pu, uppers(q))) {
                ans.push_back(false);
                continue;
            }
            int j = 0;
            bool ok = true;
            for (char c : q) {
                if (j < m && c == pattern[j]) ++j;
                else if (c >= 'A' && c <= 'Z') { ok = false; break; }
            }
            ans.push_back(ok && j == m);
        }
        return ans;
    }
};

