class Solution {
    struct UF {
        vector<int> p, r;
        int c;
        UF(int n) : p(n), r(n), c(n) { iota(p.begin(), p.end(), 0); }
        int find(int x) {
            while (p[x] != x) {
                p[x] = p[p[x]];
                x = p[x];
            }
            return x;
        }
        bool unite(int a, int b) {
            a = find(a); b = find(b);
            if (a == b) return false;
            if (r[a] < r[b]) swap(a, b);
            p[b] = a;
            if (r[a] == r[b]) ++r[a];
            --c;
            return true;
        }
    };
public:
    vector<vector<int>> findCriticalAndPseudoCriticalEdges(int n, vector<vector<int>>& edges) {
        int m = (int)edges.size();
        vector<array<int, 4>> es;
        for (int i = 0; i < m; ++i)
            es.push_back({edges[i][2], edges[i][0], edges[i][1], i});
        sort(es.begin(), es.end());
        const long long INF = (long long)4e18;
        auto kruskal = [&](int exclude, int include) {
            UF uf(n);
            long long total = 0;
            int used = 0;
            if (include >= 0) {
                for (auto& e : es)
                    if (e[3] == include) {
                        uf.unite(e[1], e[2]);
                        total += e[0];
                        ++used;
                        break;
                    }
            }
            for (auto& e : es) {
                if (e[3] == exclude || e[3] == include) continue;
                if (uf.unite(e[1], e[2])) {
                    total += e[0];
                    ++used;
                }
            }
            return used == n - 1 ? total : INF;
        };
        long long base = kruskal(-1, -1);
        vector<int> crit, pseudo;
        for (int i = 0; i < m; ++i) {
            if (kruskal(i, -1) > base) crit.push_back(i);
            else if (kruskal(-1, i) == base) pseudo.push_back(i);
        }
        return {crit, pseudo};
    }
};

