    public List<List<Integer>> findCriticalAndPseudoCriticalEdges(int n, int[][] edges) {
        int m = edges.length;
        int[][] es = new int[m][4];
        for (int i = 0; i < m; i++)
            es[i] = new int[]{edges[i][2], edges[i][0], edges[i][1], i};
        Arrays.sort(es, (a, b) -> Integer.compare(a[0], b[0]));
        long INF = (long) 4e18;
        long base = kruskal(n, es, -1, -1, INF);
        List<Integer> crit = new ArrayList<>();
        List<Integer> pseudo = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            if (kruskal(n, es, i, -1, INF) > base) crit.add(i);
            else if (kruskal(n, es, -1, i, INF) == base) pseudo.add(i);
        }
        return Arrays.asList(crit, pseudo);
    }

    private long kruskal(int n, int[][] es, int exclude, int include, long INF) {
        UF uf = new UF(n);
        long total = 0;
        int used = 0;
        if (include >= 0) {
            for (int[] e : es)
                if (e[3] == include) {
                    uf.union(e[1], e[2]);
                    total += e[0];
                    used++;
                    break;
                }
        }
        for (int[] e : es) {
            if (e[3] == exclude || e[3] == include) continue;
            if (uf.union(e[1], e[2])) {
                total += e[0];
                used++;
            }
        }
        return used == n - 1 ? total : INF;
    }
}

