class Solution:
    def findCriticalAndPseudoCriticalEdges(self, n: int, edges: List[List[int]]) -> List[List[int]]:
        class UF:
            def __init__(self, n):
                self.p = list(range(n))
                self.r = [0] * n
                self.c = n

            def find(self, x):
                while self.p[x] != x:
                    self.p[x] = self.p[self.p[x]]
                    x = self.p[x]
                return x

            def union(self, a, b):
                a, b = self.find(a), self.find(b)
                if a == b:
                    return False
                if self.r[a] < self.r[b]:
                    a, b = b, a
                self.p[b] = a
                if self.r[a] == self.r[b]:
                    self.r[a] += 1
                self.c -= 1
                return True

        es = [(w, a, b, i) for i, (a, b, w) in enumerate(edges)]
        es.sort()
        INF = 10**18

        def kruskal(exclude=-1, include=-1):
            uf = UF(n)
            total = used = 0
            if include >= 0:
                for w, a, b, i in es:
                    if i == include:
                        uf.union(a, b)
                        total += w
                        used += 1
                        break
            for w, a, b, i in es:
                if i == exclude or i == include:
                    continue
                if uf.union(a, b):
                    total += w
                    used += 1
            return total if used == n - 1 else INF

        base = kruskal()
        crit, pseudo = [], []
        for i in range(len(edges)):
            if kruskal(exclude=i) > base:
                crit.append(i)
            elif kruskal(include=i) == base:
                pseudo.append(i)
        return [crit, pseudo]

