class Solution {
    public long maxTaxiEarnings(int n, int[][] rides) {
        Arrays.sort(rides, (a, b) -> Integer.compare(a[0], b[0]));
        int m = rides.length;
        int[] starts = new int[m];
        for (int i = 0; i < m; i++) starts[i] = rides[i][0];
        long[] dp = new long[m + 1];
        for (int i = m - 1; i >= 0; i--) {
            int j = lowerBound(starts, rides[i][1]);
            long profit = (long) rides[i][1] - rides[i][0] + rides[i][2];
            dp[i] = Math.max(dp[i + 1], profit + dp[j]);
        }
        return dp[0];
    }

    private int lowerBound(int[] a, int x) {
        int lo = 0, hi = a.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (a[mid] < x) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

