public:
    int minSumOfLengths(vector<int>& arr, int target) {
        int n = (int)arr.size();
        vector<long long> pre(n + 1);
        for (int i = 0; i < n; ++i) pre[i + 1] = pre[i] + arr[i];
        const int INF = 1e9;
        vector<int> best(n + 1, INF);
        int ans = INF;
        for (int r = 1; r <= n; ++r) {
            long long need = pre[r] - target;
            int L = -1;
            auto it = lower_bound(pre.begin(), pre.begin() + r, need);
            if (it != pre.begin() + r && *it == need) L = (int)(it - pre.begin());
            best[r] = best[r - 1];
            if (L >= 0) {
                int len = r - L;
                best[r] = min(best[r], len);
                if (best[L] < INF) ans = min(ans, best[L] + len);
            }
        }
        return ans >= INF ? -1 : ans;
    }
};

