class Solution:
    def minSumOfLengths(self, arr: List[int], target: int) -> int:
        n = len(arr)
        pre = [0] * (n + 1)
        for i in range(n):
            pre[i + 1] = pre[i] + arr[i]
        INF = 10**9
        best = [INF] * (n + 1)
        ans = INF
        for r in range(1, n + 1):
            need = pre[r] - target
            lo, hi, L = 0, r - 1, -1
            while lo <= hi:
                mid = (lo + hi) // 2
                if pre[mid] == need:
                    L = mid
                    break
                if pre[mid] < need:
                    lo = mid + 1
                else:
                    hi = mid - 1
            best[r] = best[r - 1]
            if L >= 0:
                length = r - L
                best[r] = min(best[r], length)
                if best[L] < INF:
                    ans = min(ans, best[L] + length)
        return -1 if ans >= INF else ans
